            Steps = "1. Boil and mash potatoes.\n2. Sauté cumin seeds, then add peas, spices, and mashed potatoes.\n3. Roll pastry dough into circles and cut in half.\n4. Form cones from each half and fill with potato mixture.\n5. Seal edges with water.\n6. Deep fry at 350°F until golden brown.\n7. Serve with mint chutney.",
            TotalRatingPoints = 8, RatingCount = 2
        },
        new Recipe
        {
            Id = 5, Title = "Tacos al Pastor", Category = "Mexican",
            Ingredients = "Pork shoulder\nPineapple\nAchiote paste\nGuajillo chiles\nOnion\nCilantro\nCorn tortillas\nLime",
            Steps = "1. Blend achiote paste, guajillo chiles, and pineapple juice into a marinade.\n2. Marinate pork slices for at least 2 hours.\n3. Grill pork and pineapple slices until charred.\n4. Dice pork and pineapple.\n5. Warm corn tortillas.\n6. Assemble tacos with pork, pineapple, onion, and cilantro.\n7. Squeeze lime over top and serve.",
            TotalRatingPoints = 10, RatingCount = 2
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash with a fork to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
            TotalRatingPoints = 4, RatingCount = 1
        },
        new Recipe
        {
            Id = 7, Title = "Miso Ramen", Category = "Japanese",
            Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onion\nCorn\nChashu pork\nNori",
            Steps = "1. Bring chicken broth to a simmer.\n2. Whisk in miso paste, soy sauce, and sesame oil.\n3. Cook ramen noodles according to package directions.\n4. Place noodles in a bowl and ladle broth over them.\n5. Top with sliced chashu, soft-boiled egg, corn, green onion, and nori.\n6. Serve hot.",
            TotalRatingPoints = 15, RatingCount = 3
        },
        new Recipe
        {
            Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPowdered sugar",
            Steps = "1. Preheat oven to 425°F (220°C). Butter and flour ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into ramekins.\n6. Bake 12-14 minutes until edges are set but center jiggles.\n7. Invert onto plates, dust with powdered sugar, and serve immediately.",
            TotalRatingPoints = 10, RatingCount = 2
        },
    };

    private int _nextId;

    public RecipeService()
    {
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public void Add(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

