toolArgs.file_text:
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hovered ? "hovered" : "") @(star <= _selected ? "selected" : "")"
              @onmouseover="() => _hovered = star"
              @onmouseout="() => _hovered = 0"
              @onclick="() => SubmitRating(star)"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks!</span>
    }
    else
    {
        <span class="rating-label">Rate this recipe</span>
    }
</div>

<style>
    .star-rating {
        display: inline-flex;
        align-items: center;
        gap: 2px;
        font-size: 1.5rem;
        user-select: none;
    }
    .star {
        color: #ccc;
        cursor: pointer;
        transition: color 0.15s, transform 0.15s;
    }
    .star.hovered,
    .star.selected {
        color: #f5a623;
    }
    .star:hover {
        transform: scale(1.2);
    }
    .rating-label, .rating-thanks {
        font-size: 0.875rem;
        margin-left: 0.5rem;
        color: #666;
    }
    .rating-thanks {
        color: #28a745;
        font-weight: 600;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _hovered;
    private int _selected;
    private bool _submitted;

    private async Task SubmitRating(int stars)
    {
        if (_submitted) return;
        _selected = stars;
        _submitted = true;
        await OnRated.InvokeAsync(stars);
    }
}

