@page "/"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<div class="row">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-3 col-sm-6 mb-4">
            <a href="recipes/@category" class="text-decoration-none">
                <div class="card h-100 shadow-sm text-center">
                    <div class="card-body">
                        <div style="font-size: 3rem;">@GetCategoryEmoji(category)</div>
                        <h5 class="card-title mt-2">@category</h5>
                        <p class="card-text text-muted">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-3">
    <a href="submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Japanese" => "🍜",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

